import { Link } from 'react-router-dom';
import { Menu, X } from 'lucide-react';
import { useState, useEffect } from 'react';

/**
 * Header for Marcus Webb portfolio
 * Minimal editorial nav — transparent over hero, solid on scroll
 */
export default function Header() {
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [isScrolled, setIsScrolled] = useState(false);

  useEffect(() => {
    const handleScroll = () => setIsScrolled(window.scrollY > 60);
    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const navItems = [
    { href: '#about', label: 'About' },
    { href: '#contact', label: 'Contact' },
  ];

  const handleNavClick = (href: string) => {
    setIsMobileMenuOpen(false);
    const id = href.replace('#', '');
    const el = document.getElementById(id);
    if (el) el.scrollIntoView({ behavior: 'smooth' });
  };

  return (
    <header
      className={`fixed top-0 left-0 right-0 z-50 transition-all duration-500 ${
        isScrolled
          ? 'bg-background/95 backdrop-blur-sm border-b border-border'
          : 'bg-transparent'
      }`}
    >
      <div className="max-w-7xl mx-auto px-8 md:px-16">
        <div className="flex h-20 items-center justify-between">
          {/* Logo / Wordmark */}
          <Link to="/" className="flex items-center shrink-0">
            <img
              src="/airo-assets/images/logo/horizontal"
              alt="Marcus Webb"
              className="h-8 w-auto object-contain shrink-0"
            />
          </Link>

          {/* Desktop Nav */}
          <nav className="hidden md:flex items-center gap-10">
            {navItems.map((item) => (
              <button
                key={item.href}
                onClick={() => handleNavClick(item.href)}
                className="relative text-sm tracking-widest uppercase font-medium text-foreground/70 hover:text-foreground transition-colors duration-200 group"
              >
                {item.label}
                <span className="absolute -bottom-0.5 left-0 h-px w-0 bg-accent group-hover:w-full transition-all duration-300 ease-out" />
              </button>
            ))}
            <a
              href="mailto:hello@marcuswebb.co"
              className="text-sm tracking-widest uppercase font-medium text-foreground/70 hover:text-foreground transition-colors duration-200 relative group"
            >
              Hire Me
              <span className="absolute -bottom-0.5 left-0 h-px w-0 bg-accent group-hover:w-full transition-all duration-300 ease-out" />
            </a>
          </nav>

          {/* Mobile Toggle */}
          <button
            onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
            className="md:hidden p-2 text-foreground/70 hover:text-foreground transition-colors"
            aria-label="Toggle menu"
          >
            {isMobileMenuOpen ? <X size={20} /> : <Menu size={20} />}
          </button>
        </div>

        {/* Mobile Menu */}
        {isMobileMenuOpen && (
          <div className="md:hidden border-t border-border py-6 bg-background">
            <nav className="flex flex-col gap-4">
              {navItems.map((item) => (
                <button
                  key={item.href}
                  onClick={() => handleNavClick(item.href)}
                  className="text-sm tracking-widest uppercase font-medium text-foreground/70 hover:text-foreground transition-colors py-2 text-left"
                >
                  {item.label}
                </button>
              ))}
              <a
                href="mailto:hello@marcuswebb.co"
                className="text-sm tracking-widest uppercase font-medium text-foreground/70 hover:text-foreground transition-colors py-2"
                onClick={() => setIsMobileMenuOpen(false)}
              >
                Hire Me
              </a>
            </nav>
          </div>
        )}
      </div>
    </header>
  );
}

/**
 * Footer for Marcus Webb portfolio — single-line minimal editorial
 */
export default function Footer() {
  const currentYear = new Date().getFullYear();

  return (
    <footer className="border-t border-border bg-background">
      <div className="max-w-7xl mx-auto px-8 md:px-16 py-8">
        <p className="text-xs tracking-widest uppercase text-muted-foreground text-center">
          © {currentYear} Marcus Webb — All rights reserved
        </p>
      </div>
    </footer>
  );
}

import { Helmet } from '@dr.pogodin/react-helmet';
import { motion } from 'motion/react';
import { useEffect, useRef } from 'react';

// Social icon SVGs — minimal line style
function BehanceIcon() {
  return (
    <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round">
      <path d="M2 7h7.5C11.4 7 13 8.1 13 10s-1.6 3-3.5 3H2V7z" />
      <path d="M2 13h8.5C12.9 13 15 14.3 15 16.5S12.9 20 10.5 20H2v-7z" />
      <path d="M17 8h6M17.5 12.5c0-2.5 1.5-4.5 4-4.5s4 2 4 4.5H17.5z" />
      <path d="M17.5 12.5c0 2.5 1.5 4.5 4 4.5a4 4 0 0 0 3.5-2" />
    </svg>
  );
}

function InstagramIcon() {
  return (
    <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round">
      <rect x="2" y="2" width="20" height="20" rx="5" ry="5" />
      <circle cx="12" cy="12" r="4" />
      <circle cx="17.5" cy="6.5" r="0.5" fill="currentColor" />
    </svg>
  );
}

function LinkedInIcon() {
  return (
    <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round">
      <path d="M16 8a6 6 0 0 1 6 6v7h-4v-7a2 2 0 0 0-2-2 2 2 0 0 0-2 2v7h-4v-7a6 6 0 0 1 6-6z" />
      <rect x="2" y="9" width="4" height="12" />
      <circle cx="4" cy="4" r="2" />
    </svg>
  );
}

function ArrowDownIcon() {
  return (
    <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round">
      <line x1="12" y1="5" x2="12" y2="19" />
      <polyline points="19 12 12 19 5 12" />
    </svg>
  );
}

// Fade-up animation variant
const fadeUp = {
  hidden: { opacity: 0, y: 28 },
  visible: (delay: number) => ({
    opacity: 1,
    y: 0,
    transition: { duration: 0.55, delay, ease: 'easeOut' as const },
  }),
};

// Fade-in on scroll variant
const fadeIn = {
  hidden: { opacity: 0, y: 20 },
  visible: {
    opacity: 1,
    y: 0,
    transition: { duration: 0.5, ease: 'easeOut' as const },
  },
};

export default function HomePage() {
  const heroRef = useRef<HTMLDivElement>(null);

  const scrollToSection = (id: string) => {
    const el = document.getElementById(id);
    if (el) el.scrollIntoView({ behavior: 'smooth' });
  };

  return (
    <>
      <Helmet>
        <title>Marcus Webb — Freelance Graphic Designer</title>
        <meta
          name="description"
          content="Marcus Webb is a freelance graphic designer crafting brand identities, print collateral, and visual systems for clients across fashion, hospitality, and culture."
        />
      </Helmet>

      {/* ─── HERO ─────────────────────────────────────────────── */}
      <section
        ref={heroRef}
        className="relative min-h-screen flex flex-col justify-center px-8 md:px-16 overflow-hidden bg-background"
      >
        {/* Subtle background texture dot */}
        <div className="absolute top-1/4 right-16 w-px h-32 bg-border opacity-60 hidden md:block" />
        <div className="absolute top-1/4 right-16 w-1.5 h-1.5 bg-accent rounded-full -translate-x-[2px] hidden md:block" />

        <div className="max-w-7xl mx-auto w-full pt-20">
          {/* Top rule */}
          <motion.div
            className="w-full h-px bg-border mb-8 md:mb-12"
            initial={{ scaleX: 0, originX: 0 }}
            animate={{ scaleX: 1 }}
            transition={{ duration: 0.7, ease: 'easeOut' as const }}
          />

          {/* Name — architectural display */}
          <motion.h1
            className="font-heading leading-none tracking-tight text-foreground"
            style={{ fontSize: 'clamp(3.5rem, 11vw, 11rem)' }}
            variants={fadeUp}
            initial="hidden"
            animate="visible"
            custom={0.1}
          >
            Marcus Webb
          </motion.h1>

          {/* Bottom rule */}
          <motion.div
            className="w-full h-px bg-border mt-6 md:mt-8"
            initial={{ scaleX: 0, originX: 0 }}
            animate={{ scaleX: 1 }}
            transition={{ duration: 0.7, delay: 0.2, ease: 'easeOut' as const }}
          />

          {/* Tagline */}
          <motion.p
            className="mt-8 md:mt-10 text-base md:text-lg text-muted-foreground tracking-wide max-w-xl"
            variants={fadeUp}
            initial="hidden"
            animate="visible"
            custom={0.35}
          >
            Freelance Graphic Designer —{' '}
            <em className="not-italic text-foreground/80">
              crafting visual identities that endure
            </em>
          </motion.p>

          {/* CTA row */}
          <motion.div
            className="mt-10 md:mt-14 flex items-center gap-8"
            variants={fadeUp}
            initial="hidden"
            animate="visible"
            custom={0.5}
          >
            <button
              onClick={() => scrollToSection('contact')}
              className="relative text-sm tracking-widest uppercase font-medium text-foreground group"
            >
              Start a Project
              <span className="absolute -bottom-1 left-0 h-px w-full bg-accent" />
            </button>
            <button
              onClick={() => scrollToSection('about')}
              className="text-sm tracking-widest uppercase font-medium text-muted-foreground hover:text-foreground transition-colors duration-200 relative group"
            >
              Learn More
              <span className="absolute -bottom-1 left-0 h-px w-0 bg-accent group-hover:w-full transition-all duration-300 ease-out" />
            </button>
          </motion.div>
        </div>

        {/* Scroll indicator */}
        <motion.button
          onClick={() => scrollToSection('about')}
          className="absolute bottom-10 left-1/2 -translate-x-1/2 flex flex-col items-center gap-2 text-muted-foreground hover:text-foreground transition-colors duration-200"
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ delay: 1, duration: 0.6 }}
          aria-label="Scroll down"
        >
          <span className="text-xs tracking-widest uppercase">Scroll</span>
          <motion.div
            animate={{ y: [0, 5, 0] }}
            transition={{ duration: 1.8, repeat: Infinity, ease: 'easeInOut' as const }}
          >
            <ArrowDownIcon />
          </motion.div>
        </motion.button>
      </section>

      {/* ─── ABOUT ────────────────────────────────────────────── */}
      <section id="about" className="py-28 md:py-40 px-8 md:px-16 bg-background">
        <div className="max-w-7xl mx-auto">
          <motion.div
            className="grid grid-cols-1 md:grid-cols-[120px_1fr] gap-12 md:gap-20"
            variants={fadeIn}
            initial="hidden"
            whileInView="visible"
            viewport={{ once: true, margin: '-80px' }}
          >
            {/* Section number */}
            <div className="flex md:flex-col items-start gap-4">
              <span
                className="font-heading text-muted-foreground/30 leading-none select-none"
                style={{ fontSize: 'clamp(4rem, 8vw, 7rem)' }}
              >
                01
              </span>
            </div>

            {/* Content */}
            <div>
              <div className="w-8 h-px bg-accent mb-6" />
              <h2 className="font-heading text-4xl md:text-5xl text-foreground mb-10 leading-tight">
                About
              </h2>

              <div className="space-y-6 text-base md:text-lg text-muted-foreground leading-relaxed max-w-2xl">
                <p>
                  Marcus Webb is a freelance graphic designer with 8+ years of experience
                  crafting brand identities, print collateral, and visual systems for clients
                  across fashion, hospitality, and culture.
                </p>
                <p>
                  He believes great design is invisible — it communicates before words do.
                  Every project begins with listening, and ends with something that feels
                  inevitable.
                </p>
                <p>
                  Based in Los Angeles, available worldwide.
                </p>
              </div>

              {/* Skills */}
              <div className="mt-12 pt-8 border-t border-border">
                <p className="text-xs tracking-widest uppercase text-muted-foreground mb-5">
                  Disciplines
                </p>
                <div className="flex flex-wrap gap-x-6 gap-y-3">
                  {[
                    'Brand Identity',
                    'Typography',
                    'Print',
                    'Art Direction',
                    'Visual Systems',
                  ].map((skill) => (
                    <span
                      key={skill}
                      className="text-sm text-foreground/80 tracking-wide"
                    >
                      {skill}
                    </span>
                  ))}
                </div>
              </div>
            </div>
          </motion.div>
        </div>
      </section>

      {/* Divider */}
      <div className="max-w-7xl mx-auto px-8 md:px-16">
        <div className="h-px bg-border" />
      </div>

      {/* ─── CONTACT ──────────────────────────────────────────── */}
      <section id="contact" className="py-28 md:py-40 px-8 md:px-16 bg-background">
        <div className="max-w-7xl mx-auto">
          <motion.div
            className="grid grid-cols-1 md:grid-cols-[120px_1fr] gap-12 md:gap-20"
            variants={fadeIn}
            initial="hidden"
            whileInView="visible"
            viewport={{ once: true, margin: '-80px' }}
          >
            {/* Section number */}
            <div className="flex md:flex-col items-start gap-4">
              <span
                className="font-heading text-muted-foreground/30 leading-none select-none"
                style={{ fontSize: 'clamp(4rem, 8vw, 7rem)' }}
              >
                02
              </span>
            </div>

            {/* Content */}
            <div>
              <div className="w-8 h-px bg-accent mb-6" />
              <h2 className="font-heading text-4xl md:text-5xl text-foreground mb-6 leading-tight">
                Let's Work Together
              </h2>
              <p className="text-base md:text-lg text-muted-foreground mb-12 max-w-lg">
                Open to new projects and collaborations.
              </p>

              {/* Email link */}
              <a
                href="mailto:hello@marcuswebb.co"
                className="inline-block font-heading text-2xl md:text-4xl text-foreground relative group mb-14"
                style={{ fontSize: 'clamp(1.5rem, 4vw, 3rem)' }}
              >
                hello@marcuswebb.co
                <span className="absolute -bottom-1 left-0 h-px w-0 bg-accent group-hover:w-full transition-all duration-500 ease-out" />
              </a>

              {/* Social icons */}
              <div className="flex items-center gap-8 mt-4">
                <a
                  href="https://behance.net"
                  target="_blank"
                  rel="noopener noreferrer"
                  className="text-muted-foreground hover:text-foreground transition-opacity duration-200 hover:opacity-70"
                  aria-label="Behance"
                >
                  <BehanceIcon />
                </a>
                <a
                  href="https://instagram.com"
                  target="_blank"
                  rel="noopener noreferrer"
                  className="text-muted-foreground hover:text-foreground transition-opacity duration-200 hover:opacity-70"
                  aria-label="Instagram"
                >
                  <InstagramIcon />
                </a>
                <a
                  href="https://linkedin.com"
                  target="_blank"
                  rel="noopener noreferrer"
                  className="text-muted-foreground hover:text-foreground transition-opacity duration-200 hover:opacity-70"
                  aria-label="LinkedIn"
                >
                  <LinkedInIcon />
                </a>
              </div>
            </div>
          </motion.div>
        </div>
      </section>
    </>
  );
}

