import { Helmet } from '@dr.pogodin/react-helmet';
import { motion, AnimatePresence } from 'motion/react';
import { useState } from 'react';
import { Link } from 'react-router-dom';

const categories = ['All', 'Brand Identity', 'Typography', 'Packaging', 'Print', 'Art Direction'] as const;
type Category = (typeof categories)[number];

interface Project {
  id: string;
  title: string;
  client: string;
  year: string;
  category: Exclude<Category, 'All'>;
  slot: string;
  index: number;
}

const projects: Project[] = [
  {
    id: 'maison-arc',
    title: 'Maison Arc',
    client: 'Maison Arc',
    year: '2024',
    category: 'Brand Identity',
    slot: '/airo-assets/images/portfolio/brand-identity-1',
    index: 1,
  },
  {
    id: 'forma-editorial',
    title: 'Forma Editorial',
    client: 'Forma Magazine',
    year: '2024',
    category: 'Typography',
    slot: '/airo-assets/images/portfolio/typography-2',
    index: 2,
  },
  {
    id: 'sable-skincare',
    title: 'Sable Skincare',
    client: 'Sable',
    year: '2023',
    category: 'Packaging',
    slot: '/airo-assets/images/portfolio/packaging-3',
    index: 3,
  },
  {
    id: 'grove-annual',
    title: 'Grove Annual Report',
    client: 'Grove Collective',
    year: '2023',
    category: 'Print',
    slot: '/airo-assets/images/portfolio/print-4',
    index: 4,
  },
  {
    id: 'lune-campaign',
    title: 'Lune Campaign',
    client: 'Lune Studio',
    year: '2023',
    category: 'Art Direction',
    slot: '/airo-assets/images/portfolio/art-direction-5',
    index: 5,
  },
  {
    id: 'atlas-identity',
    title: 'Atlas Visual System',
    client: 'Atlas Agency',
    year: '2022',
    category: 'Brand Identity',
    slot: '/airo-assets/images/portfolio/visual-system-6',
    index: 6,
  },
];

const fadeIn = {
  hidden: { opacity: 0, y: 16 },
  visible: (i: number) => ({
    opacity: 1,
    y: 0,
    transition: { duration: 0.45, delay: i * 0.07, ease: 'easeOut' as const },
  }),
};

export default function WorkPage() {
  const [activeCategory, setActiveCategory] = useState<Category>('All');

  const filtered =
    activeCategory === 'All'
      ? projects
      : projects.filter((p) => p.category === activeCategory);

  return (
    <>
      <Helmet>
        <title>Work — Marcus Webb</title>
        <meta
          name="description"
          content="Selected projects by Marcus Webb — brand identities, typography, packaging, print, and art direction."
        />
      </Helmet>

      <div className="min-h-screen bg-background pt-32 pb-28 px-8 md:px-16">
        <div className="max-w-7xl mx-auto">

          {/* Page header */}
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5, ease: 'easeOut' as const }}
            className="mb-16 md:mb-20"
          >
            <div className="w-8 h-px bg-accent mb-6" />
            <h1 className="font-heading text-5xl md:text-7xl text-foreground leading-none mb-6">
              Selected Work
            </h1>
            <p className="text-muted-foreground text-base md:text-lg max-w-md">
              A curated collection of projects across brand, print, and visual systems.
            </p>
          </motion.div>

          {/* Filter bar */}
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ duration: 0.4, delay: 0.2 }}
            className="flex flex-wrap gap-x-8 gap-y-3 mb-14 border-b border-border pb-8"
          >
            {categories.map((cat) => (
              <button
                key={cat}
                onClick={() => setActiveCategory(cat)}
                className={`text-xs tracking-widest uppercase font-medium transition-colors duration-200 relative group pb-1 ${
                  activeCategory === cat
                    ? 'text-foreground'
                    : 'text-muted-foreground hover:text-foreground'
                }`}
              >
                {cat}
                <span
                  className={`absolute -bottom-0 left-0 h-px bg-accent transition-all duration-300 ease-out ${
                    activeCategory === cat ? 'w-full' : 'w-0 group-hover:w-full'
                  }`}
                />
              </button>
            ))}
          </motion.div>

          {/* Grid */}
          <motion.div
            layout
            className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-x-8 gap-y-14"
          >
            <AnimatePresence mode="popLayout">
              {filtered.map((project, i) => (
                <motion.div
                  key={project.id}
                  layout
                  variants={fadeIn}
                  initial="hidden"
                  animate="visible"
                  exit={{ opacity: 0, scale: 0.97, transition: { duration: 0.2 } }}
                  custom={i}
                >
                  <Link to={`/work/${project.id}`} className="group block">
                    {/* Image */}
                    <div className="relative overflow-hidden bg-muted aspect-[4/3] mb-5">
                      <img
                        src={project.slot}
                        alt={project.title}
                        className="w-full h-full object-cover transition-transform duration-700 ease-out group-hover:scale-105"
                      />
                      {/* Hover overlay */}
                      <div className="absolute inset-0 bg-foreground/0 group-hover:bg-foreground/10 transition-colors duration-400" />
                      {/* Category badge */}
                      <div className="absolute top-4 left-4 opacity-0 group-hover:opacity-100 transition-opacity duration-300">
                        <span className="text-xs tracking-widest uppercase bg-background/90 text-foreground px-3 py-1.5">
                          {project.category}
                        </span>
                      </div>
                    </div>

                    {/* Meta */}
                    <div className="flex items-start justify-between">
                      <div>
                        <h2 className="font-heading text-xl text-foreground leading-tight mb-1 group-hover:text-accent transition-colors duration-200">
                          {project.title}
                        </h2>
                        <p className="text-sm text-muted-foreground">{project.client}</p>
                      </div>
                      <span className="text-xs text-muted-foreground mt-1 shrink-0 ml-4">
                        {project.year}
                      </span>
                    </div>
                  </Link>
                </motion.div>
              ))}
            </AnimatePresence>
          </motion.div>

          {/* Empty state */}
          {filtered.length === 0 && (
            <div className="py-24 text-center text-muted-foreground text-sm tracking-widest uppercase">
              No projects in this category yet.
            </div>
          )}
        </div>
      </div>
    </>
  );
}

