import { Link, useLocation, useNavigate } from 'react-router-dom';
import { Menu, X } from 'lucide-react';
import { useState, useEffect } from 'react';

/**
 * Header for Marcus Webb portfolio
 * Minimal editorial nav — transparent over hero, solid on scroll
 */
export default function Header() {
  const location = useLocation();
  const navigate = useNavigate();
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [isScrolled, setIsScrolled] = useState(false);

  const isHome = location.pathname === '/';

  useEffect(() => {
    const handleScroll = () => setIsScrolled(window.scrollY > 60);
    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const scrollToAnchor = (id: string) => {
    const el = document.getElementById(id);
    if (el) el.scrollIntoView({ behavior: 'smooth' });
  };

  const handleAnchorNav = (anchor: string) => {
    setIsMobileMenuOpen(false);
    if (isHome) {
      scrollToAnchor(anchor);
    } else {
      navigate('/');
      // Wait for navigation then scroll
      setTimeout(() => scrollToAnchor(anchor), 100);
    }
  };

  return (
    <header
      className={`fixed top-0 left-0 right-0 z-50 transition-all duration-500 ${
        isScrolled || !isHome
          ? 'bg-background/95 backdrop-blur-sm border-b border-border'
          : 'bg-transparent'
      }`}
    >
      <div className="max-w-7xl mx-auto px-8 md:px-16">
        <div className="flex h-20 items-center justify-between">
          {/* Logo / Wordmark */}
          <Link to="/" className="flex items-center shrink-0">
            <img
              src="/airo-assets/images/logo/horizontal"
              alt="Marcus Webb"
              className="h-8 w-auto object-contain shrink-0"
            />
          </Link>

          {/* Desktop Nav */}
          <nav className="hidden md:flex items-center gap-10">
            <Link
              to="/work"
              className={`relative text-sm tracking-widest uppercase font-medium transition-colors duration-200 group ${
                location.pathname === '/work' ? 'text-foreground' : 'text-foreground/70 hover:text-foreground'
              }`}
            >
              Work
              <span className={`absolute -bottom-0.5 left-0 h-px bg-accent transition-all duration-300 ease-out ${
                location.pathname === '/work' ? 'w-full' : 'w-0 group-hover:w-full'
              }`} />
            </Link>
            <button
              onClick={() => handleAnchorNav('about')}
              className="relative text-sm tracking-widest uppercase font-medium text-foreground/70 hover:text-foreground transition-colors duration-200 group"
            >
              About
              <span className="absolute -bottom-0.5 left-0 h-px w-0 bg-accent group-hover:w-full transition-all duration-300 ease-out" />
            </button>
            <a
              href="mailto:hello@marcuswebb.co"
              className="text-sm tracking-widest uppercase font-medium text-foreground/70 hover:text-foreground transition-colors duration-200 relative group"
            >
              Hire Me
              <span className="absolute -bottom-0.5 left-0 h-px w-0 bg-accent group-hover:w-full transition-all duration-300 ease-out" />
            </a>
          </nav>

          {/* Mobile Toggle */}
          <button
            onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
            className="md:hidden p-2 text-foreground/70 hover:text-foreground transition-colors"
            aria-label="Toggle menu"
          >
            {isMobileMenuOpen ? <X size={20} /> : <Menu size={20} />}
          </button>
        </div>

        {/* Mobile Menu */}
        {isMobileMenuOpen && (
          <div className="md:hidden border-t border-border py-6 bg-background">
            <nav className="flex flex-col gap-4">
              <Link
                to="/work"
                className="text-sm tracking-widest uppercase font-medium text-foreground/70 hover:text-foreground transition-colors py-2"
                onClick={() => setIsMobileMenuOpen(false)}
              >
                Work
              </Link>
              <button
                onClick={() => handleAnchorNav('about')}
                className="text-sm tracking-widest uppercase font-medium text-foreground/70 hover:text-foreground transition-colors py-2 text-left"
              >
                About
              </button>
              <a
                href="mailto:hello@marcuswebb.co"
                className="text-sm tracking-widest uppercase font-medium text-foreground/70 hover:text-foreground transition-colors py-2"
                onClick={() => setIsMobileMenuOpen(false)}
              >
                Hire Me
              </a>
            </nav>
          </div>
        )}
      </div>
    </header>
  );
}

