import { Helmet } from '@dr.pogodin/react-helmet';
import { motion } from 'motion/react';
import { useState } from 'react';
import { useForm } from 'react-hook-form';
import { CheckCircle } from 'lucide-react';

const PROJECT_TYPES = [
  'Brand Identity',
  'Packaging',
  'Print & Editorial',
  'Art Direction',
  'Visual System',
  'Other',
] as const;

const BUDGETS = [
  'Under $5k',
  '$5k – $15k',
  '$15k – $30k',
  '$30k – $60k',
  '$60k+',
  'Not sure yet',
] as const;

interface FormValues {
  name: string;
  email: string;
  company: string;
  projectType: string;
  budget: string;
  message: string;
}

const fadeIn = {
  hidden: { opacity: 0, y: 16 },
  visible: (delay = 0) => ({
    opacity: 1,
    y: 0,
    transition: { duration: 0.5, delay, ease: 'easeOut' as const },
  }),
};

export default function ContactPage() {
  const [submitted, setSubmitted] = useState(false);
  const [selectedType, setSelectedType] = useState('');
  const [selectedBudget, setSelectedBudget] = useState('');

  const {
    register,
    handleSubmit,
    setValue,
    formState: { errors, isSubmitting },
  } = useForm<FormValues>();

  const onSubmit = async (data: FormValues) => {
    // Simulate a brief send delay
    await new Promise((r) => setTimeout(r, 800));
    console.log('Form submitted:', data);
    setSubmitted(true);
  };

  const selectType = (type: string) => {
    setSelectedType(type);
    setValue('projectType', type, { shouldValidate: true });
  };

  const selectBudget = (budget: string) => {
    setSelectedBudget(budget);
    setValue('budget', budget, { shouldValidate: true });
  };

  return (
    <>
      <Helmet>
        <title>Contact — Marcus Webb</title>
        <meta
          name="description"
          content="Start a project with Marcus Webb — freelance graphic designer based in Los Angeles."
        />
      </Helmet>

      <div className="min-h-screen bg-background pt-32 pb-28 px-8 md:px-16">
        <div className="max-w-7xl mx-auto">
          <div className="grid grid-cols-1 lg:grid-cols-[1fr_480px] gap-16 lg:gap-24">

            {/* Left — intro */}
            <motion.div
              variants={fadeIn}
              initial="hidden"
              animate="visible"
              custom={0}
            >
              <div className="w-8 h-px bg-accent mb-6" />
              <h1 className="font-heading leading-none text-foreground mb-8"
                style={{ fontSize: 'clamp(2.8rem, 6vw, 6rem)' }}>
                Let's Work<br />Together
              </h1>
              <p className="text-base md:text-lg text-muted-foreground leading-relaxed max-w-md mb-12">
                Tell me about your project. I take on a limited number of clients each quarter to ensure every engagement gets the attention it deserves.
              </p>

              {/* Contact details */}
              <div className="space-y-6">
                <div>
                  <p className="text-xs tracking-widest uppercase text-muted-foreground mb-2">Email</p>
                  <a
                    href="mailto:hello@marcuswebb.co"
                    className="text-foreground font-heading text-xl relative group inline-block"
                  >
                    hello@marcuswebb.co
                    <span className="absolute -bottom-0.5 left-0 h-px w-0 bg-accent group-hover:w-full transition-all duration-400 ease-out" />
                  </a>
                </div>
                <div className="h-px bg-border" />
                <div>
                  <p className="text-xs tracking-widest uppercase text-muted-foreground mb-2">Based in</p>
                  <p className="text-foreground">Los Angeles, CA — Available Worldwide</p>
                </div>
                <div className="h-px bg-border" />
                <div>
                  <p className="text-xs tracking-widest uppercase text-muted-foreground mb-3">Response time</p>
                  <p className="text-foreground text-sm">Within 48 hours</p>
                </div>
              </div>
            </motion.div>

            {/* Right — form */}
            <motion.div
              variants={fadeIn}
              initial="hidden"
              animate="visible"
              custom={0.15}
            >
              {submitted ? (
                <motion.div
                  initial={{ opacity: 0, scale: 0.97 }}
                  animate={{ opacity: 1, scale: 1 }}
                  transition={{ duration: 0.4, ease: 'easeOut' as const }}
                  className="h-full flex flex-col justify-center py-16"
                >
                  <CheckCircle size={40} className="text-accent mb-6" strokeWidth={1.5} />
                  <h2 className="font-heading text-3xl text-foreground mb-4">Message Sent</h2>
                  <p className="text-muted-foreground leading-relaxed max-w-sm">
                    Thank you for reaching out. I'll review your inquiry and be in touch within 48 hours.
                  </p>
                </motion.div>
              ) : (
                <form onSubmit={handleSubmit(onSubmit)} className="space-y-8" noValidate>

                  {/* Name + Email */}
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                    <div>
                      <label className="block text-xs tracking-widest uppercase text-muted-foreground mb-2">
                        Name <span className="text-accent">*</span>
                      </label>
                      <input
                        {...register('name', { required: 'Required' })}
                        placeholder="Your name"
                        className={`w-full bg-transparent border-b py-3 text-foreground placeholder:text-muted-foreground/50 text-sm outline-none transition-colors duration-200 focus:border-foreground ${
                          errors.name ? 'border-destructive' : 'border-border'
                        }`}
                      />
                      {errors.name && (
                        <p className="text-xs text-destructive mt-1">{errors.name.message}</p>
                      )}
                    </div>
                    <div>
                      <label className="block text-xs tracking-widest uppercase text-muted-foreground mb-2">
                        Email <span className="text-accent">*</span>
                      </label>
                      <input
                        {...register('email', {
                          required: 'Required',
                          pattern: { value: /^\S+@\S+\.\S+$/, message: 'Invalid email' },
                        })}
                        type="email"
                        placeholder="your@email.com"
                        className={`w-full bg-transparent border-b py-3 text-foreground placeholder:text-muted-foreground/50 text-sm outline-none transition-colors duration-200 focus:border-foreground ${
                          errors.email ? 'border-destructive' : 'border-border'
                        }`}
                      />
                      {errors.email && (
                        <p className="text-xs text-destructive mt-1">{errors.email.message}</p>
                      )}
                    </div>
                  </div>

                  {/* Company */}
                  <div>
                    <label className="block text-xs tracking-widest uppercase text-muted-foreground mb-2">
                      Company / Studio
                    </label>
                    <input
                      {...register('company')}
                      placeholder="Optional"
                      className="w-full bg-transparent border-b border-border py-3 text-foreground placeholder:text-muted-foreground/50 text-sm outline-none transition-colors duration-200 focus:border-foreground"
                    />
                  </div>

                  {/* Project type chips */}
                  <div>
                    <label className="block text-xs tracking-widest uppercase text-muted-foreground mb-3">
                      Project Type <span className="text-accent">*</span>
                    </label>
                    <input
                      type="hidden"
                      {...register('projectType', { required: 'Please select a project type' })}
                    />
                    <div className="flex flex-wrap gap-2">
                      {PROJECT_TYPES.map((type) => (
                        <button
                          key={type}
                          type="button"
                          onClick={() => selectType(type)}
                          className={`px-4 py-2 text-xs tracking-widest uppercase border transition-colors duration-200 ${
                            selectedType === type
                              ? 'border-foreground bg-foreground text-background'
                              : 'border-border text-muted-foreground hover:border-foreground hover:text-foreground'
                          }`}
                        >
                          {type}
                        </button>
                      ))}
                    </div>
                    {errors.projectType && (
                      <p className="text-xs text-destructive mt-2">{errors.projectType.message}</p>
                    )}
                  </div>

                  {/* Budget chips */}
                  <div>
                    <label className="block text-xs tracking-widest uppercase text-muted-foreground mb-3">
                      Budget Range
                    </label>
                    <input type="hidden" {...register('budget')} />
                    <div className="flex flex-wrap gap-2">
                      {BUDGETS.map((b) => (
                        <button
                          key={b}
                          type="button"
                          onClick={() => selectBudget(b)}
                          className={`px-4 py-2 text-xs tracking-widest uppercase border transition-colors duration-200 ${
                            selectedBudget === b
                              ? 'border-foreground bg-foreground text-background'
                              : 'border-border text-muted-foreground hover:border-foreground hover:text-foreground'
                          }`}
                        >
                          {b}
                        </button>
                      ))}
                    </div>
                  </div>

                  {/* Message */}
                  <div>
                    <label className="block text-xs tracking-widest uppercase text-muted-foreground mb-2">
                      Tell me about your project <span className="text-accent">*</span>
                    </label>
                    <textarea
                      {...register('message', { required: 'Required' })}
                      rows={5}
                      placeholder="What are you working on? What's the timeline? Any context that would help..."
                      className={`w-full bg-transparent border-b py-3 text-foreground placeholder:text-muted-foreground/50 text-sm outline-none transition-colors duration-200 focus:border-foreground resize-none ${
                        errors.message ? 'border-destructive' : 'border-border'
                      }`}
                    />
                    {errors.message && (
                      <p className="text-xs text-destructive mt-1">{errors.message.message}</p>
                    )}
                  </div>

                  {/* Submit */}
                  <div className="pt-2">
                    <button
                      type="submit"
                      disabled={isSubmitting}
                      className="relative text-sm tracking-widest uppercase font-medium text-foreground group disabled:opacity-50 disabled:cursor-not-allowed"
                    >
                      {isSubmitting ? 'Sending...' : 'Send Inquiry'}
                      <span className="absolute -bottom-1 left-0 h-px w-full bg-accent" />
                    </button>
                  </div>
                </form>
              )}
            </motion.div>
          </div>
        </div>
      </div>
    </>
  );
}

